"""Human-readable exact-key ledger and complete non-FPS benchmark tables."""
def report(stats,bench,focused):
 n=lambda x:f'{x:,}'.replace(',',' ')
 p=stats['after_percent'];bar='█'*round(p*30/100)+'░'*(30-round(p*30/100))
 out=['# Перевод NPC — 0.15.101','',f'`{bar}` **{p:.2f}%** точных ключей публичной очереди. Полоса округлена.','','| Показатель | До | После |','| --- | ---: | ---: |','| Точные ключи | 10 391 · 63,97% | 10 776 · 66,34% |','| Без подтверждённого ключа | 5 853 | 5 468 · 33,66% |','| Всего в зафиксированной очереди | 16 244 | 16 244 |','','Это не процент готовности всей игры. В очереди есть исторические, тестовые, нейтральные, редакторские строки и переменные. Закрытые скрипты сервера не выгружены; часть динамических переводов работает без отдельного точного ключа.','','## Этот проход','','385 новых реплик / 79 обозначений говорящего, включая 12 телефонных реплик. Шесть точных групп ответов / семь подписей / шесть опубликованных оформлений. Сверены 83 страницы: 82 ревизии совпали; на Professor Wynd изменилась только запись истории, полные диалоги и условия совпадают.','','| Говорящий | Новых ключей |','| --- | ---: |']
 out += [f'| {name} | {count} |' for name,count in stats['new_by_speaker'].items()]
 out+=['| Всего | 385 |','','544 выбранные строки: 385 новых, 136 прежних, 16 с переменными, 6 нейтральных, 1 прежний динамический перевод. Отдельно сохранена одна неоднозначно оформленная кнопка. Исправлена офлайн-классификация одной постоянной реплики Fragilis. Alpha-условия, стандартный островной NPC и звуки животных не объявлены полноценными новыми сюжетными ветками.','','[Контекстная вычитка](NPC_0.15.101_REVIEW_NOTES.md) · [Все говорящие и остаток](NPC_ALL_SPEAKERS_0.15.101_RU.md).','','## Проверки','',f'171 группа заново проверена на окончательном JAR, плюс 15 тестов извлечения. Новые реплики: {n(stats["new_fixture_assertions"])} проверок; кнопки: {n(stats["new_choice_fixture_assertions"])}. Проверяется стиль каждого символа: цвета, курсив, свежие клики и подсказки, числа, дробление компонентов, счётчики, время, пользовательские замены, подписанный/пользовательский чат.','','На выборке из 11 248 строк все 385 новых переводов совпали с ожидаемыми в обычном и опубликованном цветном виде. Остальные 10 863 результата не изменились. 72 прежних пробела цветного распознавания не объявлены исправленными.','','## Оптимизация','','Сравнение 0.15.100 → 0.15.101. Новые ключи загружаются в существующий словарь при запуске; число обработчиков и покадровых проходов не увеличено. Исполняемые инструкции вне стартовых таблиц совпали; остальные классы, включая HUD/F3, побайтно те же. Расход памяти при загрузке словаря увеличивается — нулевое влияние не обещается.','','Используемая пользователем 0.15.96 и отключённая 0.15.92 не изменены. Игра не перезапускалась, JAR автоматически не установлен.','','Ниже изолированные измерения, не FPS, GPU, время кадра или 0,1% lows. По четыре отдельные JVM в порядке 100 → 101 → 101 → 100, оба порядка и все раунды сохранены. Время относится к сообщению/операции, не ко всему кадру.']
 def table(family,title):
  out.extend(['',f'### {title}','','| Сценарий | Одинаковая полезная работа | До → после, мкс | Изменение, оба порядка | Байты до → после |','| --- | --- | ---: | ---: | ---: |'])
  for r in family['summary']:
   times=' / '.join(f'{o["before_ns"]/1000:.3f} → {o["after_ns"]/1000:.3f}' for o in r['orders']);change=' / '.join(f'{o["wall_change_percent"]:+.1f}%' for o in r['orders']);memory=' / '.join(f'{o["before_bytes"]:.0f} → {o["after_bytes"]:.0f}' for o in r['orders']);out.append(f'| {r["mode"]} | {"Да" if r["equal_useful_output"] else "Нет: новый перевод"} | {times} | {change} | {memory} |')
 for name,f in bench['families'].items():table(f,name)
 out+=['','В двух new_* сценариях только новая версия переводит текст. Это разная полезная работа: проценты этих сценариев не являются регрессией одинакового пути.','','Контрольный длинный повтор: ещё четыре JVM, шесть прежних сценариев, увеличенный прогрев. Он дополняет, а не заменяет первые результаты.']
 table(focused,'Контрольный повтор')
 changes=[o['wall_change_percent'] for r in focused['summary'] for o in r['orders']]
 out+=['',f'Диапазон контрольного повтора: {min(changes):+.1f}%…{max(changes):+.1f}%. Все результаты сохранены. Это не доказывает отсутствие микролагов в игре.','','## Остаток','','5 468 строк без подтверждённого точного ключа. Продолжается работа над NPC, динамическими обращениями, меню, историческими условиями и качеством извлечения. Все NPC и весь Абифон не объявляются завершёнными.','',f'SHA-256 JAR: `{stats["runtime_jar_sha256"]}`.']
 return '\n'.join(out)+'\n'
